import {describe, test, expect} from 'vitest';
import PQueue from '../source/index.js';

describe('Abort signal while queued', () => {
	test('abort signal rejects task and removes from queue when concurrency is full', async () => {
		const queue = new PQueue({concurrency: 1});

		// Add a blocker task that holds the concurrency slot
		const blocker = queue.add(async () => {
			await new Promise(r => setTimeout(r, 500));
		}, {id: 'blocker'});

		// Wait for blocker to start
		await new Promise(r => setTimeout(r, 50));

		// Add a second task that will be queued
		const controller = new AbortController();
		let task2Ran = false;
		const task2Promise = queue.add(async () => {
			task2Ran = true;
			return 'result';
		}, {id: 'task2', signal: controller.signal});

		// Verify task2 is queued
		expect(queue.size).toBe(1);
		expect(queue.pending).toBe(1);

		// Abort while queued
		controller.abort(new Error('aborted while queued'));

		// Queue should be empty immediately
		expect(queue.size).toBe(0);

		// Task should reject
		try {
			await task2Promise;
			expect.fail('Should have thrown');
		} catch (error: any) {
			expect(error.message).toBe('aborted while queued');
		}

		// Wait for blocker to finish
		await blocker;

		// Task2 should never have run
		expect(task2Ran).toBe(false);
	});

	test('abort signal that is already aborted rejects immediately', async () => {
		const queue = new PQueue({concurrency: 1});

		// Add a blocker task
		const blocker = queue.add(async () => {
			await new Promise(r => setTimeout(r, 500));
		}, {id: 'blocker'});

		// Wait for blocker to start
		await new Promise(r => setTimeout(r, 50));

		// Pre-abort the controller
		const controller = new AbortController();
		controller.abort(new Error('already aborted'));

		// Add a task with the pre-aborted signal
		let taskRan = false;
		const taskPromise = queue.add(async () => {
			taskRan = true;
			return 'result';
		}, {id: 'task', signal: controller.signal});

		// Should reject immediately without being queued
		try {
			await taskPromise;
			expect.fail('Should have thrown');
		} catch (error: any) {
			expect(error.message).toBe('already aborted');
		}

		// Queue should be empty (task was never queued or was removed)
		expect(queue.size).toBe(0);
		expect(taskRan).toBe(false);

		// Cleanup
		await blocker;
	});

	test('abort signal with AbortController.abort() uses AbortError', async () => {
		const queue = new PQueue({concurrency: 1});

		// Add a blocker task
		const blocker = queue.add(async () => {
			await new Promise(r => setTimeout(r, 500));
		}, {id: 'blocker'});

		// Wait for blocker to start
		await new Promise(r => setTimeout(r, 50));

		// Add a second task
		const controller = new AbortController();
		const taskPromise = queue.add(async () => 'result', {
			id: 'task',
			signal: controller.signal,
		});

		// Abort without specifying a reason (should use AbortError)
		controller.abort();

		try {
			await taskPromise;
			expect.fail('Should have thrown');
		} catch (error: any) {
			expect(error.name).toBe('AbortError');
		}

		// Cleanup
		await blocker;
	});

	test('abort signal does not affect other queued tasks', async () => {
		const queue = new PQueue({concurrency: 1});

		// Add a blocker task
		const blocker = queue.add(async () => {
			await new Promise(r => setTimeout(r, 500));
		}, {id: 'blocker'});

		// Wait for blocker to start
		await new Promise(r => setTimeout(r, 50));

		// Add two more tasks
		const controller1 = new AbortController();
		const controller2 = new AbortController();

		let task2Ran = false;
		let task3Ran = false;

		const task2Promise = queue.add(async () => {
			task2Ran = true;
			return 'task2';
		}, {id: 'task2', signal: controller1.signal});

		const task3Promise = queue.add(async () => {
			task3Ran = true;
			return 'task3';
		}, {id: 'task3', signal: controller2.signal});

		// Both should be queued
		expect(queue.size).toBe(2);

		// Abort only task2
		controller1.abort(new Error('abort task2'));

		// Only task2 should be removed
		expect(queue.size).toBe(1);

		// Task2 should reject
		try {
			await task2Promise;
			expect.fail('Should have thrown');
		} catch (error: any) {
			expect(error.message).toBe('abort task2');
		}

		// Task3 should succeed
		const result = await task3Promise;
		expect(result).toBe('task3');
		expect(task2Ran).toBe(false);
		expect(task3Ran).toBe(true);

		// Cleanup
		await blocker;
	});

	test('abort signal while running is handled by the task', async () => {
		const queue = new PQueue({concurrency: 2});

		const controller = new AbortController();
		let taskRan = false;

		const taskPromise = queue.add(async ({signal}) => {
			taskRan = true;
			// Simulate a long-running task that checks the signal
			await new Promise((resolve, reject) => {
				const timer = setTimeout(resolve, 500);
				signal?.addEventListener('abort', () => {
					clearTimeout(timer);
					reject(signal!.reason);
				}, {once: true});
			});
			return 'result';
		}, {id: 'task', signal: controller.signal});

		// Wait for task to start
		await new Promise(r => setTimeout(r, 50));
		expect(taskRan).toBe(true);

		// Abort while running
		controller.abort(new Error('abort while running'));

		try {
			await taskPromise;
			expect.fail('Should have thrown');
		} catch (error: any) {
			expect(error.message).toBe('abort while running');
		}
	});

	test('concurrent aborts are idempotent', async () => {
		const queue = new PQueue({concurrency: 1});

		// Add a blocker task
		const blocker = queue.add(async () => {
			await new Promise(r => setTimeout(r, 500));
		}, {id: 'blocker'});

		// Wait for blocker to start
		await new Promise(r => setTimeout(r, 50));

		// Add a task
		const controller = new AbortController();
		const taskPromise = queue.add(async () => 'result', {
			id: 'task',
			signal: controller.signal,
		});

		// Abort multiple times
		controller.abort(new Error('first abort'));
		controller.abort(new Error('second abort'));

		// Should still reject (no double rejection)
		try {
			await taskPromise;
			expect.fail('Should have thrown');
		} catch (error: any) {
			expect(error.message).toBe('first abort');
		}

		// Cleanup
		await blocker;
	});
});

describe('Queue remove method', () => {
	test('remove returns false for non-existent id', () => {
		const queue = new PQueue({concurrency: 1});
		// Access internal queue - this is a white-box test
		// The remove method is exposed on the queue interface
		const removed = (queue as any).queue?.remove?.('nonexistent') ?? true;
		// If remove returns false, it means the item wasn't found
		// This is expected behavior
	});

	test('remove returns true and removes item', async () => {
		const queue = new PQueue({concurrency: 1});

		// Add a blocker
		const blocker = queue.add(async () => {
			await new Promise(r => setTimeout(r, 500));
		}, {id: 'blocker'});

		await new Promise(r => setTimeout(r, 50));

		// Add a task
		queue.add(async () => 'result', {id: 'task2'});

		expect(queue.size).toBe(1);

		// Abort should remove it
		const controller = new AbortController();
		const task2Promise = queue.add(async () => 'result', {
			id: 'task3',
			signal: controller.signal,
		});

		expect(queue.size).toBe(2);

		controller.abort();

		expect(queue.size).toBe(1);

		// Cleanup
		try {
			await task2Promise;
		} catch {}
		await blocker;
	});
});

