import PQueue from "./source/index.js";

async function main() {
    // Queue with concurrency 1
    const queue = new PQueue({ concurrency: 1 });

    // Add a task that takes some time (will hold the concurrency slot)
    const blocker = queue.add(async () => {
        console.log("blocker started");
        await new Promise(r => setTimeout(r, 2000));
        console.log("blocker finished");
    }, { id: 'blocker' });

    // Add a second task - this will be queued
    const controller = new AbortController();
    const task2Promise = queue.add(async () => {
        console.log("task2 executed (should not happen)");
        return "result";
    }, { id: 'task2', signal: controller.signal });

    // Wait a bit for task2 to be queued
    await new Promise(r => setTimeout(r, 100));

    console.log(`Queue size before abort: ${queue.size}`);
    console.log(`Pending before abort: ${queue.pending}`);

    // Abort the signal while task2 is still queued
    controller.abort(new Error("aborted while queued"));

    try {
        const result = await task2Promise;
        console.log(`BUG: Task2 resolved with ${result} (should have rejected)`);
    } catch (error: any) {
        console.log(`Task2 rejected with: ${error.message} (expected)`);
    }

    // Wait for blocker to finish
    await blocker;

    console.log(`Queue size after everything: ${queue.size}`);
    console.log(`Pending after everything: ${queue.pending}`);

    if (queue.size > 0) {
        console.log("BUG CONFIRMED: Task2 is still in the queue after abort!");
    }
}

main().catch(console.error);

