		const queue = new PQueue({concurrency: 1});
		// Access internal queue - this is a white-box test
		// The remove method is exposed on the queue interface
		const removed = (queue as any).queue?.remove?.('nonexistent') ?? true;
		// If remove returns false, it means the item wasn't found
		// This is expected behavior
	});

