			let abortListener: (() => void) | undefined;
			let settled = false;

			const safeResolve = (value: TaskResultType) => {
				if (settled) {
					return;
				}

				settled = true;
				resolve(value);
			};

			const safeReject = (reason: unknown) => {
				if (settled) {
